rules.text:
@keyframes origin-reveal { 
  0% { opacity: 0; transform: translateY(-4px); }
  100% { opacity: 1; transform: translateY(0px); }
}

rules.decl:
background: color-mix(
            in srgb,
            var(--color-bg-surface, rgb(245 251 252)) 72%,
            transparent
        ); backdrop-filter: blur(20px);

rules.text:
@keyframes location-arrive { 
  0% { opacity: 0; transform: translateY(-4px); }
  100% { opacity: 1; transform: translateY(0px); }
}

@keyframes today-menu-in { 
  0% { opacity: 0; transform: translateY(5px); }
  100% { opacity: 1; transform: translateY(0px); }
}

@keyframes today-composer-glow { 
  100% { transform: rotate(360deg); }
}

@keyframes today-composer-spin { 
  0% { transform: rotate(90deg) scale(1.08); }
  100% { transform: rotate(450deg) scale(1.08); }
}

@keyframes today-launcher-return { 
  0% { opacity: 0; transform: scale(0.8) rotate(-20deg); }
  100% { opacity: 1; transform: scale(1) rotate(0deg); }
}

@keyframes time-options-in { 
  0% { opacity: 0; }
  100% { opacity: 1; }
}

rules.decl:
transition: background-color 180ms ease,
        border-color 180ms ease,
        scale 160ms var(--motion-settle);

rules.text:
@keyframes contextual-reveal { 
  0% { opacity: 0; transform: translateY(5px) scale(0.99); }
  100% { opacity: 1; transform: translateY(0px) scale(1); }
}

@keyframes backdrop-reveal { 
  0% { opacity: 0; }
  100% { opacity: 1; }
}

@keyframes event-art-settle { 
  0% { transform: scale(1.06); opacity: 0.75; }
  100% { transform: scale(1); opacity: 1; }
}

rules.decl:
content: ""; position: absolute; inset: 0px; z-index: -1; pointer-events: none; background: linear-gradient(
        to bottom,
        transparent,
        color-mix(in srgb, var(--event-canvas) 65%, transparent) 40%,
        color-mix(in srgb, var(--event-canvas) 94%, transparent)
    ); backdrop-filter: blur(12px); mask-image: linear-gradient(transparent, black 55%);

grid-template-columns: repeat(
        auto-fit,
        minmax(
            max(
                260px,
                calc(
                    (100% - (var(--festival-columns, 3) - 1) * 22px) /
                        var(--festival-columns, 3)
                )
            ),
            1fr
        )
    );

background: linear-gradient(
        to bottom,
        transparent,
        color-mix(in srgb, var(--surface) 92%, transparent) 22px,
        var(--surface) 70%
    );

background: linear-gradient(
        transparent,
        color-mix(in srgb, var(--color-bg-canvas) 92%, transparent) 38%,
        var(--color-bg-canvas) 70%
    );

background: linear-gradient(
            color-mix(in srgb, var(--color-bg-canvas) 96%, transparent) 68%,
            transparent
        );

position: fixed; inset: auto 0px 0px; z-index: 45; display: grid; grid-template-columns: repeat(5, minmax(0px, 1fr)); gap: 0px; margin: 0px; padding: 6px 6px max(6px, env(safe-area-inset-bottom, 0px)); border-top: 1px solid var(--color-border, #e6ddcb); background: color-mix(
            in srgb,
            var(--color-bg-header, #fffdf8) 96%,
            transparent
        ); backdrop-filter: blur(8px); transition: translate var(--duration-base, 180ms) ease; view-transition-name: section-bar;

